import { AxisScale } from '@visx/axis';
import { getTicks } from '@visx/scale';
import React from 'react';

import { DivAxisWrapper } from './DivAxisWrapper.js';
import { getTickValues } from '../../../functions/format-value.js';
import { getHorizontalNumTicks } from '../../../functions/ticks.js';
import { TickValueFormatter } from '../../../types/tick-value.js';
import { AxisBottom } from '../AxisBottom.js';
import { axisFontProps } from '../constants.js';
import { getTickLabelPropsForValueAxis } from '../functions/get-tick-label-props.js';

/**
 * @internal
 */
export interface OldValueBottomAxisProps {
  scale: AxisScale;
  containerWidth: number;
  containerHeight: number;
  formatter?: TickValueFormatter;
  label?: string;
  stroke?: string;
}

const TICK_LABEL_PROPS = getTickLabelPropsForValueAxis('bottom');

/**
 * @internal
 */
export const OldValueBottomAxis = (props: OldValueBottomAxisProps) => {
  const { scale, containerWidth, containerHeight, label, formatter, stroke } =
    props;
  const numTicks = getHorizontalNumTicks(containerWidth);
  const ticks = getTicks(scale, numTicks);
  const tickValues = getTickValues(ticks, formatter);
  const tickFormat = (_: unknown, index: number) => tickValues[index];

  return (
    <DivAxisWrapper
      divAxisStyle={axisFontProps}
      ticks={tickValues}
      label={label}
      isTickVertical
    >
      <AxisBottom
        data-testid="value-axis-bottom"
        scale={scale}
        containerSize={containerWidth}
        height={containerHeight}
        numTicks={numTicks}
        tickValues={ticks}
        tickLabelProps={TICK_LABEL_PROPS}
        tickFormat={tickFormat}
        label={label}
        stroke={stroke}
      />
    </DivAxisWrapper>
  );
};

OldValueBottomAxis['displayName'] = 'ValueBottomAxis';
